"use strict";(globalThis.webpackChunkgrc||=[]).push([[64588],{51527(e){e.exports=JSON.parse('{"citeKey":"gurbani2005inhibitorsubiquitous","slug":"gurbani-2005-inhibitors-ubiquitous-a804","title":"Inhibitors for the Ubiquitous Deployment of Services in the Next Generation Network","authors":["V. K. Gurbani","X.-H. Sun","A. Brusilovsky"],"venue":"IEEE Communications, vol. 43, no. 9","type":"Journal","entryType":"article","date":"January, 2005","year":2005,"era":"iit","month":1,"doi":"10.1109/mcom.2005.1509976","abstract":"The next-generation network is characterized by the merging of the Internet, telecommunica- tions, and information technology. As envisioned some six years ago, the NGN was to revolutionize the lives of its users by providing them the best of the services of the PSTN and the Internet, written rapidly by IT programmers. Service providers were to be similarly affected by the increase in revenues paid by the users of these new services. Equip- ment vendors would have a difficult time keeping inventories of the NGN infrastructure. The truth has been somewhat different. In this article we characterize a set of inhibitors - technical, regu- latory, and business-related that are affecting the ubiquitous deployment of NGN services.","hasAbstract":true,"lede":"The next-generation network is characterized by the merging of the Internet, telecommunica- tions, and information technology.","links":{"pdf":"https://grc.iit.edu/papers/2005/gurbani-2005-inhibitors-ubiquitous-a804.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);